import {completedExams,completedRetries,mastery} from './workshop-exam-history.mjs';
import {grade} from './workshop-exam-model.mjs';
import {caseInfo} from './workshop-content.mjs';
const p=(es,en)=>({es,en});
export function mountExamHistory(api){const root=document.createElement('section');root.id='examHistory';root.className='challenge-panel';document.querySelector('main').append(root);const el=(tag,text,host)=>{const n=document.createElement(tag);n.textContent=text;host.append(n);return n;},t=x=>x[api.lang()],score=e=>Math.round(e.cases.reduce((n,c)=>n+grade(c).score,0)/4);
return {render(){root.replaceChildren();el('h2',t(p('Historial de exámenes','Exam history')),root);let exams=[],retries=[];try{exams=completedExams(localStorage);retries=completedRetries(localStorage);}catch{}
el('p',t(p('Hasta 25 exámenes y 100 reintentos en este navegador. Las notas originales no cambian. Los reintentos practican un caso conocido y se muestran por separado; no son un examen nuevo ni una reparación verificada.','Up to 25 exams and 100 retries in this browser. Original scores never change. Retries practise a known case and are shown separately; they are neither a new exam nor a verified repair.')),root);
if(api.busy()){el('p',t(p('Termina o abandona el intento activo para consultar respuestas anteriores.','Finish or abandon the active attempt to inspect previous answers.')),root);const cancel=el('button',t(p('Abandonar intento activo','Abandon active attempt')),root);cancel.id='abandonAttempt';cancel.onclick=api.cancel;return;}
if(!exams.length){el('p',t(p('Termina tu primer examen para comparar resultados.','Finish your first exam to compare results.')),root);return;}
const recent=exams.at(-1),previous=exams.at(-2);el('p',t(p('Última nota: ','Latest score: '))+score(recent)+'/100 · '+t(p('Cambio frente al anterior: ','Change from previous: '))+(previous?(score(recent)-score(previous)>0?'+':'')+(score(recent)-score(previous)): '—'),root);
el('p',t(p('Compara también la dificultad de cada caso. Un cambio de nota con fallos más complejos no equivale necesariamente a perder dominio.','Compare each case’s difficulty too. A score change with more complex faults does not necessarily mean lost mastery.')),root);
const rows=mastery(exams,retries);for(const type of ['measurement','diagnosis']){const details=el('details','',root);details.open=type==='measurement';el('summary',t(type==='measurement'?p('Progreso por medición','Progress by measurement'):p('Progreso por diagnóstico','Progress by diagnosis')),details);el('p',t(p('Cada caso cuenta una vez por habilidad; en intermitencias deben acertarse ambos momentos. Consistencia: al menos 3 casos y los últimos 3 correctos. Con menos de 6 casos, las ventanas inicial y reciente se superponen. Los reintentos no elevan esa clasificación.','Each case counts once per skill; intermittent readings must be correct at both moments. Consistency means at least 3 cases and the latest 3 correct. With fewer than 6 cases, the first and latest windows overlap. Retries do not raise that classification.')),details);
for(const r of rows.filter(r=>r.type===type)){const card=el('article','',details);el('h4',api.name(r.kind)+' · '+(type==='measurement'?t(caseInfo[r.kind].tests[r.id]):api.faultName(r.kind,r.id)),card);const tally=a=>a.length?a.filter(Boolean).length+'/'+a.length:'—';el('p',t(p('Primeros 3 / últimos 3 / reintentos correctos: ','First 3 / latest 3 / correct retries: '))+tally(r.exams.slice(0,3))+' · '+tally(r.exams.slice(-3))+' · '+tally(r.retries),card);el('strong',t(r.status==='consistent'?p('Consistente en los últimos exámenes','Consistent in recent exams'):r.status==='early'?p('Todavía pocos datos','Not enough evidence yet'):p('Necesita repaso','Needs practice')),card);}}
for(const [offset,e]of exams.slice().reverse().entries()){const card=el('article','',root);el('h3',new Date(e.finished).toLocaleString(api.lang())+' · '+score(e)+'/100',card);card.dataset.examId=e.id;for(const [index,c]of e.cases.entries()){const g=grade(c),line=el('div','',card);el('p',api.name(c.kind)+' · '+api.faultName(c.kind,c.fault)+' · '+g.score+'/100 · '+g.readings.filter(r=>!r.correct).length+' '+t(p('lecturas incorrectas','incorrect readings'))+' · '+t(g.diagnosis?p('diagnóstico correcto','correct diagnosis'):p('diagnóstico incorrecto','incorrect diagnosis')),line);const view=el('button',t(p('Revisar en 3D','Review in 3D')),line);view.dataset.archiveReview=e.id+':'+index;view.onclick=()=>api.review(e,index);if(g.score<100){const b=el('button',t(p('Reintentar este caso','Retry this case')),line);b.dataset.retryCase=e.id+':'+index;b.onclick=()=>api.retry(e,index);const attempts=retries.filter(r=>r.retryOf===e.id&&r.retryIndex===index);if(attempts.length)el('p',attempts.length+' '+t(p('reintentos · original / último: ','retries · original / latest: '))+g.score+' / '+grade(attempts.at(-1).cases[index]).score,line);}}}
}};
}
